            (#"^ログ ([0-9/]+ [0-9:]+)$"#, "Log %@"),
            (#"^macOS ([0-9.]+)（(.+)）$"#, "macOS %@ (%@)"),
            (#"^sysdiagnoseからasptool_snapshot.logを取り出せませんでした（終了コード([0-9-]+)）$"#, "Could not copy asptool_snapshot.log out of the sysdiagnose (exit code %@)"),
            (#"^(.+)（時刻差 ([+−-]?[0-9.]+)時間）$"#, "%@ (time difference %@ h)"),
            (#"^(.+) ／ (.+)・差 ([+−-]?[0-9.]+%?)$"#, "%@ / %@ · difference %@"),
            (#"^([0-9.]+ GB) ／ ([0-9.]+ GB)$"#, "%@ / %@"),
            (#"^ログイン時起動を変更できませんでした: (.+)$"#, "Could not change Open at Login: %@"),
            (#"^研究セッション履歴を読み込めません: (.+)$"#, "Could not load the research session history: %@"),
            (#"^Reliability Event Journalを読み込めませんでした: (.+)$"#, "Could not load the Reliability Event Journal: %@"),
            (#"^(.+)（管理者認証）$"#, "%@ (administrator)"),
            (#"^(.+)を生成・取得中…$"#, "Running %@…"),
            (#"^(.+)の取得完了。解析中…$"#, "%@ read. Analyzing…"),
            (#"^(.+)は終了コード([0-9-]+)。metadataを解析中…$"#, "%@ exited with code %@. Analyzing metadata…"),
            (#"^(.+)の取得・解析完了$"#, "%@ read and analyzed"),
            (#"^(.+)の取得は終了コード([0-9-]+)。metadata解析完了$"#, "%@ exited with code %@. Metadata analyzed"),
            (#"^(.+)の実行に失敗しました$"#, "%@ could not be run"),
            (#"^SMARTとの照合に失敗したため保存せず、自動取得を停止しました: (.+)$"#, "The read did not match SMART, so it was not saved and automatic collection stopped: %@"),
            (#"^FTLの値が足りないため保存しませんでした: (.+)$"#, "The FTL read lacks a required value, so it was not saved: %@"),
            (#"^SMARTと照合できないため保存しませんでした: (.+)$"#, "The read could not be checked against SMART, so it was not saved: %@"),
            (#"^(.+)。設定から手動で1回取得し、SMARTと照合できれば自動取得を始めます$"#, "%@. Read it once by hand from Settings; automatic collection starts once it matches SMART"),
            (#"^macOS ([0-9]+) でのDirect FTLの取得値がSMARTと一致しました。このMacでは自動取得を有効にします$"#, "The Direct FTL read on macOS %@ matched SMART. Automatic collection is now on for this Mac"),
            (#"^macOS ([0-9]+) はこのMacでSMARTと照合済みです$"#, "macOS %@ has been checked against SMART on this Mac"),
            (#"^macOS build (.+) はまだ確認していません$"#, "macOS build %@ has not been reviewed yet"),
            (#"^FTL all（定期取得） · ([0-9]+) records$"#, "FTL all (scheduled) · %@ records"),
            (#"^最終成功: (.+) · (.+)$"#, "Last successful read: %@ · %@"),
            (#"^最終成功: (.+)$"#, "Last successful read: %@"),
            (#"^取得成功（一時データを保持）: (.+)$"#, "Read succeeded (temporary data kept): %@"),
            (#"^FTL allの定期取得に失敗しました: (.+)$"#, "Scheduled FTL all read failed: %@"),
            (#"^([0-9]+)回続けて失敗したため自動取得を停止しました（設定から再開できます）: (.+)$"#, "Automatic collection stopped after %@ failures in a row (resume it in Settings): %@"),
            (#"^参考TBW (.+)（([0-9]+) TBW/TB・(.+)）$"#, "Reference TBW %@ (%@ TBW/TB · %@)"),
            (#"^(.+)・世代対応未確認の市販品参考値$"#, "retail reference for %@; NAND generation not confirmed"),
            (#"^(.+)と同世代NANDの市販品$"#, "retail drives with the same NAND generation as %@"),
            (#"^(D[1-8]): (.+)$"#, "%@: %@"),
            (#"^build provenance: (.+) → (.+)$"#, "Build provenance: %@ → %@"),
            (#"^初回 (.+?): (.+)$"#, "Initial assessment %@: %@"),
            (#"^最終判定 (.+)$"#, "Latest assessment %@"),
            (#"^率学習除外 (.+) → (.+)（境界後72時間を含む）$"#, "Rate-learning exclusion %@ → %@ (includes 72 hours after the boundary)"),
            (#"^(Core wearの対応表|Direct形式|probe版|取得経路|対応表のbuild|抽出版) (.+)$"#, "%@ %@"),
            (#"^(.+)/日$"#, "%@/day"),
            (#"^([0-9/]+ [0-9:]+) (.+)$"#, "%@ %@")
        ]
        return entries.compactMap { pattern, format in
            guard let expression = try? NSRegularExpression(pattern: pattern) else { return nil }
            return Rule(expression: expression, format: format)
        }
    }()
    static func translate(_ source: String, language: String) -> String? {
        guard !language.lowercased().hasPrefix("ja") else { return nil }
        let range = NSRange(source.startIndex..<source.endIndex, in: source)
        for rule in rules {
            guard let match = rule.expression.firstMatch(in: source, range: range), match.range == range else { continue }
            let values: [CVarArg] = (1..<match.numberOfRanges).compactMap { index in
                guard let captured = Range(match.range(at: index), in: source) else { return nil }
                return UIString.readout(String(source[captured]), language: language)
            }
            guard values.count == match.numberOfRanges - 1 else { return nil }
            return String(format: rule.format, arguments: values)
        }
        return nil
    }
}
